def apply_employee_rate_to_drafts(apps, schema_editor):
    """Draft salaries get the employee's own CNSS now (D-119); approved ones are history and stay as they were."""
    from decimal import ROUND_HALF_UP, Decimal

    Record = apps.get_model("hr", "SalaryRecord")
    for record in Record.objects.filter(status="draft").select_related("employee"):
        rate = record.employee.employee_cnss_rate
        own = (record.gross * rate / 100).quantize(Decimal("0.001"), rounding=ROUND_HALF_UP)
        net = record.gross - own - record.deductions
        if net < 0:
            continue
        record.employee_cnss_rate, record.employee_cnss, record.net = rate, own, net
        record.save(update_fields=["employee_cnss_rate", "employee_cnss", "net"])


